 "<b style=\"font-size:54px;color:#f4f1ea\">4</b><br>ciclos": "<b style=\"font-size:54px;color:#f4f1ea\">4</b><br>series",
 "<b style=\"font-size:54px;color:#f4f1ea\">92</b><br>músicos": "<b style=\"font-size:54px;color:#f4f1ea\">92</b><br>musicians",
